3	/**
4	 * Line-buffered NDJSON parser for Claude stream events.
5	 * Mirrors the Swift ClaudeStreamParser actor.
6	 */
7	export class ClaudeStreamParser {
8	  private buffer = '';
9	
10	  parse(text: string): ClaudeStreamEvent[] {
11	    this.buffer += text;
12	    const events: ClaudeStreamEvent[] = [];
13	
14	    while (true) {
15	      const newlineIndex = this.buffer.indexOf('\n');
16	      if (newlineIndex === -1) break;
17	
18	      const line = this.buffer.slice(0, newlineIndex);
19	      this.buffer = this.buffer.slice(newlineIndex + 1);
20	
21	      if (!line.trim()) continue;
22	
23	      try {
24	        const json = JSON.parse(line);
25	        const event = parseClaudeEvent(json);
26	        if (event) events.push(event);
27	      } catch {
28	        // Skip unparseable lines (forward compatibility)
29	      }
30	    }
31	
32	    return events;
33	  }
34	
35	  flush(): ClaudeStreamEvent[] {
36	    if (!this.buffer.trim()) {
37	      this.buffer = '';
38	      return [];
39	    }
40	
