71	
72	function classifyCodexAuthIssue(raw: string): string | undefined {
73	  const text = raw.toLowerCase();
74	  const matchesAuthIssue =
75	    text.includes('codex login') ||
76	    text.includes('not logged') ||
77	    text.includes('authentication') ||
78	    text.includes('unauthorized') ||
79	    text.includes('forbidden') ||
80	    text.includes('openai_api_key') ||
81	    text.includes('api key') ||
82	    text.includes('login required') ||
83	    text.includes('chatgpt login') ||
84	    text.includes('status code: 401') ||
85	    text.includes('status code: 403');
86	
87	  if (!matchesAuthIssue) return undefined;
88	
89	  return [
90	    'Codex is not authenticated in this sprite environment.',
91	    'Run `codex login status` and then `codex login` inside the sprite shell, or switch this chat to Claude.',
92	  ].join(' ');
93	}
94	
95	function messagePlainText(message: ChatMessage): string {
96	  return message.content
97	    .filter((item): item is Extract<ChatContent, { type: 'text' }> => item.type === 'text')
98	    .map((item) => item.text)
99	    .join('\n\n')
100	    .trim();
101	}
102	
103	function buildFallbackPrompt(history: ChatMessage[], prompt: string): string {
104	  const transcript = history
105	    .filter((message) => message.role === 'user' || message.role === 'assistant')
106	    .map((message) => {
107	      const text = messagePlainText(message);
108	      if (!text) return null;
109	      const role = message.role === 'user' ? 'User' : 'Assistant';
110	      const clipped = text.length > 1200 ? `${text.slice(0, 1200)}...` : text;
111	      return `${role}: ${clipped}`;
112	    })
113	    .filter((line): line is string => line !== null)
114	    .slice(-12);
115	
116	  if (transcript.length === 0) return prompt;
117	
118	  return [
119	    'Continue this conversation. Here is the prior transcript:',
120	    transcript.join('\n\n'),
121	    `User: ${prompt}`,
122	    'Assistant:',
123	  ].join('\n\n');
124	}
125	
126	function countUserMessages(messages: ChatMessage[]): number {
127	  return messages.reduce((n, m) => (m.role === 'user' ? n + 1 : n), 0);
128	}
129	
130	/** Stable content fingerprint — two conversations with the same signature render identically. */
131	function conversationSignature(messages: ChatMessage[]): string {
132	  return messages
133	    .map((m) => {
134	      const parts = m.content.map((c) => {
135	        if (c.type === 'text') return `t:${c.text}`;
136	        if (c.type === 'reasoning') return `r:${c.text.length}`;
137	        if (c.type === 'toolUse') return `u:${c.card.toolUseId}`;
138	        if (c.type === 'toolResult') return `R:${c.card.toolUseId}`;
139	        return c.type;
140	      });
141	      return `${m.role}|${parts.join('|')}`;
142	    })
143	    .join('\n');
144	}
145	
146	/**
147	 * Overlay an incoming (e.g. on-disk transcript) conversation onto the local one,
148	 * preserving the existing message ids for the common prefix. Keeping ids stable
149	 * means React reuses the already-mounted bubbles instead of remounting/re-scrolling
150	 * them — which is what made reopening a chat look like the last turn was duplicated
151	 * and re-answered.
152	 */
153	function mergeTranscript(local: ChatMessage[], incoming: ChatMessage[]): ChatMessage[] {
154	  return incoming.map((msg, i) => {
155	    const localMsg = local[i];
156	    if (localMsg && localMsg.role === msg.role) {
157	      return { ...msg, id: localMsg.id };
158	    }
159	    return msg;
160	  });
161	}
162	
163	function nextAssistantAfterUser(messages: ChatMessage[], userIndex: number): number {
164	  for (let i = userIndex + 1; i < messages.length; i++) {
165	    if (messages[i].role === 'user') break;
166	    if (messages[i].role === 'assistant') return i;
167	  }
168	  return -1;
169	}
170	
171	function debugChat(...args: unknown[]) {
172	  if (!__DEV__) return;
173	  // eslint-disable-next-line no-console
174	  console.log('[chat-debug]', ...args);
175	}
176	
177	export function useChat(options: UseChatOptions) {
178	  const { spriteName, chatId, workingDirectory, provider } = options;
179	
180	  const [messages, setMessages] = useState<ChatMessage[]>([]);
181	  const [status, setStatus] = useState<ChatStatus>('idle');
182	  const [modelName, setModelName] = useState<string | undefined>();
183	  const [errorMessage, setErrorMessage] = useState<string | undefined>();
184	  const [inputText, setInputText] = useState('');
185	  const [codexAuthIssue, setCodexAuthIssue] = useState<string | undefined>();
186	
187	  const claudeSessionIdRef = useRef<string | undefined>(options.initialClaudeSessionId);
188	  const codexSessionIdRef = useRef<string | undefined>(options.initialCodexSessionId);
189	  const activeRunRef = useRef<ActiveChatRun | undefined>(options.initialActiveRun);
190	  const execSessionIdRef = useRef<string | undefined>(undefined);
191	  const abortRef = useRef<AbortController | null>(null);
192	  const claudeParserRef = useRef(new ClaudeStreamParser());
193	  const codexParserRef = useRef(new CodexStreamParser());
194	  const loadRequestRef = useRef(0);
195	  const messagesRef = useRef<ChatMessage[]>([]);
196	  const activeUserMessageIdRef = useRef<string | undefined>(undefined);
197	  const activeAssistantMessageIdRef = useRef<string | undefined>(undefined);
198	  const toolUseIndexRef = useRef<Map<string, { messageIndex: number; toolName: string }>>(new Map());
199	  const processedUUIDsRef = useRef<Set<string>>(new Set());
200	  const statusRef = useRef<ChatStatus>('idle');
201	  const assistantTextSeenRef = useRef(false);
202	  const serviceEventsSeenRef = useRef(0);
203	  const codexStderrRef = useRef('');
204	  const codexSawAssistantRef = useRef(false);
205	  const processServiceEventRef = useRef<(event: ServiceLogEvent) => void>(() => {});
206	
207	  const setStatusTracked = useCallback((s: ChatStatus) => {
208	    statusRef.current = s;
209	    setStatus(s);
210	  }, []);
211	
212	  const emitSessionIds = useCallback(() => {
213	    options.onSessionIdsChange?.({
214	      claudeSessionId: claudeSessionIdRef.current,
215	      codexSessionId: codexSessionIdRef.current,
216	    });
217	  }, [options.onSessionIdsChange]);
218	
219	  const setActiveRun = useCallback(
220	    (activeRun: ActiveChatRun | undefined) => {
221	      activeRunRef.current = activeRun;
222	      options.onActiveRunChange?.(activeRun);
223	    },
224	    [options.onActiveRunChange]
225	  );
226	
227	  const setClaudeSessionId = useCallback(
228	    (sessionId: string | undefined) => {
229	      if (claudeSessionIdRef.current === sessionId) return;
230	      claudeSessionIdRef.current = sessionId;
231	      emitSessionIds();
232	    },
233	    [emitSessionIds]
234	  );
235	
236	  const setCodexSessionId = useCallback(
237	    (sessionId: string | undefined) => {
238	      if (codexSessionIdRef.current === sessionId) return;
239	      codexSessionIdRef.current = sessionId;
240	      emitSessionIds();
241	    },
242	    [emitSessionIds]
243	  );
244	
245	  const isStreaming = status === 'streaming' || status === 'connecting' || status === 'reconnecting';
246	
247	  const updateMessages = useCallback((updater: (prev: ChatMessage[]) => ChatMessage[]) => {
248	    setMessages((prev) => {
249	      const next = updater(prev);
250	      messagesRef.current = next;
251	      return next;
252	    });
253	  }, []);
254	
255	  const persistMessages = useCallback(
256	    async (msgs?: ChatMessage[]) => {
257	      await saveChatMessages(chatId, msgs ?? messagesRef.current);
258	    },
259	    [chatId]
260	  );
261	
262	  const syncClaudeTranscript = useCallback(
263	    async (loadRequest: number, resumeId: string | undefined) => {
264	      if (provider !== 'claude' || !resumeId) return;
265	
266	      try {
267	        const transcript = await readClaudeSessionMessages(spriteName, resumeId);
268	        if (loadRequest !== loadRequestRef.current) return;
269	        if (statusRef.current !== 'idle') return;
270	        if (transcript.length === 0) return;
271	        const local = messagesRef.current;
272	        const transcriptTurns = countUserMessages(transcript);
273	        const localTurns = countUserMessages(local);
274	        // The app may already have persisted the user's in-flight turn before
275	        // it was closed. In that case the turn counts are equal, but the
276	        // transcript can now contain the completed assistant response.
277	        if (local.length !== 0 && transcriptTurns < localTurns) return;
278	        const merged = mergeTranscript(local, transcript);
279	        if (conversationSignature(merged) === conversationSignature(local)) return;
280	        messagesRef.current = merged;
281	        setMessages(merged);
282	        await saveChatMessages(chatId, merged);
283	      } catch {
284	        // Offline / no transcript yet — keep the local copy.
285	      }
286	    },
287	    [chatId, provider, spriteName]
288	  );
289	
290	  const loadSession = useCallback(async () => {
291	    const loadRequest = ++loadRequestRef.current;
292	    const initialMessageCount = messagesRef.current.length;
293	    const saved = await loadChatMessages(chatId);
294	    if (loadRequest !== loadRequestRef.current) return;
295	
296	    // Avoid clobbering live in-memory messages if a send started while loading persisted history.
297	    if (messagesRef.current.length > initialMessageCount || statusRef.current !== 'idle') return;
298	
299	    messagesRef.current = saved;
300	    setMessages(saved);
301	    activeRunRef.current = options.initialActiveRun;
302	    activeUserMessageIdRef.current = undefined;
303	    activeAssistantMessageIdRef.current = undefined;
304	    assistantTextSeenRef.current = false;
305	
306	    setClaudeSessionId(options.initialClaudeSessionId);
307	    setCodexSessionId(options.initialCodexSessionId);
308	
309	    const index = new Map<string, { messageIndex: number; toolName: string }>();
310	    saved.forEach((msg, idx) => {
311	      msg.content.forEach((item) => {
312	        if (item.type === 'toolUse') {
313	          index.set(item.card.toolUseId, { messageIndex: idx, toolName: item.card.toolName });
314	        }
315	      });
316	    });
317	    toolUseIndexRef.current = index;
318	
319	    if (saved.length === 0) {
320	      processedUUIDsRef.current = new Set();
321	      claudeParserRef.current.reset();
322	      codexParserRef.current.reset();
323	    }
324	
325	    const activeRun = options.initialActiveRun;
326	    if (activeRun && activeRun.provider === provider) {
327	      activeUserMessageIdRef.current = activeRun.userMessageId;
328	      activeAssistantMessageIdRef.current = activeRun.assistantMessageId;
329	      execSessionIdRef.current = activeRun.execSessionId;
330	      processedUUIDsRef.current = new Set();
331	      claudeParserRef.current.reset();
332	      codexParserRef.current.reset();
333	      codexStderrRef.current = '';
334	      codexSawAssistantRef.current = false;
335	      serviceEventsSeenRef.current = 0;
336	      setStatusTracked('reconnecting');
337	
338	      (async () => {
339	        const controller = new AbortController();
340	        abortRef.current = controller;
341	        try {
342	          await api.streamExec(
343	            spriteName,
344	            [],
345	            (event) => processServiceEventRef.current(event),
346	            controller.signal,
347	            { attachSessionId: activeRun.execSessionId }
348	          );
349	        } catch (err: any) {
350	          if (err.name !== 'AbortError') {
351	            debugChat('active exec attach failed', provider, err.message ?? err);
352	          }
353	        } finally {
354	          if (abortRef.current === controller) {
355	            abortRef.current = null;
356	          }
357	          execSessionIdRef.current = undefined;
358	          activeUserMessageIdRef.current = undefined;
359	          activeAssistantMessageIdRef.current = undefined;
360	          assistantTextSeenRef.current = false;
361	          setActiveRun(undefined);
362	          setStatusTracked('idle');
363	          await syncClaudeTranscript(loadRequest, options.initialClaudeSessionId);
364	          await persistMessages();
365	        }
366	      })();
367	      return;
368	    }
369	
370	    if (activeRun) {
371	      setActiveRun(undefined);
372	    }
373	
374	    // Source-of-truth sync: if this chat resumes a known Claude session, pull its
375	    // on-disk transcript from the sprite. Catches turns that finished (or were
376	    // started from a terminal / another device) while the app was away — the same
377	    // history `claude --resume` would show. Runs in the background; guarded so it
378	    // never clobbers a fresh local send.
379	    syncClaudeTranscript(loadRequest, options.initialClaudeSessionId);
380	  }, [
381	    chatId,
382	    options.initialActiveRun,
383	    options.initialClaudeSessionId,
384	    options.initialCodexSessionId,
385	    persistMessages,
386	    provider,
387	    setClaudeSessionId,
388	    setCodexSessionId,
389	    setActiveRun,
390	    setStatusTracked,
391	    spriteName,
392	    syncClaudeTranscript,
393	  ]);
394	
395	  const ensureAssistantTarget = useCallback(
396	    (source: ChatMessage[]): { messages: ChatMessage[]; index: number } => {
397	      let messages = source;
398	      const activeId = activeAssistantMessageIdRef.current;
399	      const activeUserId = activeUserMessageIdRef.current;
400	
401	      if (activeId) {
402	        const byId = messages.findIndex((m) => m.id === activeId && m.role === 'assistant');
403	        if (byId !== -1) return { messages, index: byId };
404	      }
405	
406	      if (activeUserId) {
407	        const userIndex = messages.findIndex((m) => m.id === activeUserId && m.role === 'user');
408	        if (userIndex !== -1) {
409	          const existingAfterUser = nextAssistantAfterUser(messages, userIndex);
410	          if (existingAfterUser !== -1) {
411	            activeAssistantMessageIdRef.current = messages[existingAfterUser].id;
412	            return { messages, index: existingAfterUser };
413	          }
414	
415	          const assistant: ChatMessage = {
416	            id: activeId ?? makeId(),
417	            timestamp: Date.now(),
418	            role: 'assistant',
419	            content: [],
420	          };
421	          messages = [...messages];
422	          messages.splice(userIndex + 1, 0, assistant);
423	          activeAssistantMessageIdRef.current = assistant.id;
424	          return { messages, index: userIndex + 1 };
425	        }
426	      }
427	
428	      let lastUserIndex = -1;
429	      for (let i = messages.length - 1; i >= 0; i--) {
430	        if (messages[i].role === 'user') {
431	          lastUserIndex = i;
432	          break;
433	        }
434	      }
435	
436	      for (let i = messages.length - 1; i > lastUserIndex; i--) {
437	        if (messages[i].role === 'assistant') {
438	          activeAssistantMessageIdRef.current = messages[i].id;
439	          return { messages, index: i };
440	        }
441	      }
442	
443	      const assistant: ChatMessage = {
444	        id: activeId ?? makeId(),
445	        timestamp: Date.now(),
446	        role: 'assistant',
447	        content: [],
448	      };
449	      messages = [...messages, assistant];
450	      activeAssistantMessageIdRef.current = assistant.id;
451	      return { messages, index: messages.length - 1 };
452	    },
453	    []
454	  );
455	
456	  const updateActiveAssistant = useCallback(
457	    (mutateContent: (content: ChatContent[], targetIndex: number) => ChatContent[]) => {
458	      updateMessages((prev) => {
459	        const { messages: resolved, index: targetIndex } = ensureAssistantTarget([...prev]);
460	        const msgs = [...resolved];
461	        const target = msgs[targetIndex];
462	        msgs[targetIndex] = {
463	          ...target,
464	          content: mutateContent([...target.content], targetIndex),
465	        };
466	        return msgs;
467	      });
468	    },
469	    [ensureAssistantTarget, updateMessages]
470	  );
471	
472	  const appendAssistantText = useCallback(
473	    (text: string) => {
474	      if (!text) return;
475	      debugChat('appendAssistantText', provider, 'chars', text.length);
476	      updateActiveAssistant((newContent) => {
477	        assistantTextSeenRef.current = true;
478	        const lastContent = newContent[newContent.length - 1];
479	        if (lastContent && lastContent.type === 'text') {
480	          newContent[newContent.length - 1] = {
481	            type: 'text',
482	            text: lastContent.text + text,
483	          };
484	        } else {
485	          newContent.push({ type: 'text', text });
486	        }
487	        return newContent;
488	      });
489	    },
490	    [updateActiveAssistant]
491	  );
492	
493	  const ensureTurnAssistantText = useCallback(
494	    (text: string) => {
495	      if (!text.trim()) return;
496	      updateMessages((prev) => {
497	        const activeUserId = activeUserMessageIdRef.current;
498	        if (!activeUserId) return prev;
499	
500	        const msgs = [...prev];
501	        const userIndex = msgs.findIndex((m) => m.id === activeUserId && m.role === 'user');
502	        if (userIndex === -1) return prev;
503	
504	        let assistantIndex = nextAssistantAfterUser(msgs, userIndex);
505	        if (assistantIndex === -1) {
506	          debugChat('ensureTurnAssistantText insert', provider, 'userIndex', userIndex);
507	          const assistant: ChatMessage = {
508	            id: makeId(),
509	            timestamp: Date.now(),
510	            role: 'assistant',
511	            content: [{ type: 'text', text }],
512	          };
513	          msgs.splice(userIndex + 1, 0, assistant);
514	          activeAssistantMessageIdRef.current = assistant.id;
515	          assistantTextSeenRef.current = true;
516	          return msgs;
517	        }
518	
519	        const assistant = msgs[assistantIndex];
520	        const hasVisibleText = assistant.content.some(
521	          (item) => item.type === 'text' && item.text.trim().length > 0
522	        );
523	        if (hasVisibleText) return msgs;
524	
525	        debugChat('ensureTurnAssistantText append', provider, 'assistantIndex', assistantIndex);
526	        msgs[assistantIndex] = {
527	          ...assistant,
528	          content: [...assistant.content, { type: 'text', text }],
529	        };
530	        activeAssistantMessageIdRef.current = msgs[assistantIndex].id;
531	        assistantTextSeenRef.current = true;
532	        return msgs;
533	      });
534	    },
535	    [provider, updateMessages]
536	  );
537	
538	  const handleClaudeEvent = useCallback(
539	    (event: ClaudeStreamEvent) => {
540	      switch (event.type) {
541	        case 'system': {
542	          const sys = event.event as ClaudeSystemEvent;
543	          setClaudeSessionId(sys.session_id);
544	          if (sys.model) setModelName(sys.model);
545	          break;
546	        }
547	        case 'assistant': {
548	          const asst = event.event as ClaudeAssistantEvent;
549	          debugChat('claude assistant event', asst.message.content.map((b) => b.type));
550	          updateActiveAssistant((newContent, targetIndex) => {
551	            for (const block of asst.message.content) {
552	              if (block.type === 'text' && 'text' in block) {
553	                if (block.text) assistantTextSeenRef.current = true;
554	                const lastContent = newContent[newContent.length - 1];
555	                if (lastContent && lastContent.type === 'text') {
556	                  newContent[newContent.length - 1] = {
557	                    type: 'text',
558	                    text: lastContent.text + block.text,
559	                  };
560	                } else {
561	                  newContent.push({ type: 'text', text: block.text });
562	                }
563	              } else if (block.type === 'thinking' && 'thinking' in block) {
564	                // Extended-thinking blocks — surface Claude's reasoning live.
565	                const thinkingText = (block as { thinking?: string }).thinking ?? '';
566	                if (thinkingText) {
567	                  const lastContent = newContent[newContent.length - 1];
568	                  if (lastContent && lastContent.type === 'reasoning') {
569	                    newContent[newContent.length - 1] = {
570	                      type: 'reasoning',
571	                      text: lastContent.text + thinkingText,
572	                    };
573	                  } else {
574	                    newContent.push({ type: 'reasoning', text: thinkingText });
575	                  }
576	                }
577	              } else if (block.type === 'tool_use' && 'id' in block && 'name' in block) {
578	                const card: ToolUseCard = {
579	                  toolUseId: block.id,
580	                  toolName: block.name,
581	                  input: block.input,
582	                  startedAt: Date.now(),
583	                };
584	                newContent.push({ type: 'toolUse', card });
585	                toolUseIndexRef.current.set(block.id, {
586	                  messageIndex: targetIndex,
587	                  toolName: block.name,
588	                });
589	              }
590	            }
591	            return newContent;
592	          });
593	          break;
594	        }
595	        case 'user': {
596	          const toolResult = event.event as ClaudeToolResultEvent;
597	          updateActiveAssistant((newContent) => {
598	            for (const result of toolResult.message.content) {
599	              const toolName = toolUseIndexRef.current.get(result.tool_use_id)?.toolName ?? 'Unknown';
600	              const resultCard: ToolResultCard = {
601	                toolUseId: result.tool_use_id,
602	                toolName,
603	                content: result.content ?? null,
604	                completedAt: Date.now(),
605	              };
606	
607	              newContent.push({ type: 'toolResult', card: resultCard });
608	
609	              for (let i = 0; i < newContent.length; i++) {
610	                const item = newContent[i];
611	                if (item.type === 'toolUse' && item.card.toolUseId === result.tool_use_id) {
612	                  newContent[i] = {
613	                    type: 'toolUse',
614	                    card: { ...item.card, result: resultCard },
615	                  };
616	                  break;
617	                }
618	              }
619	            }
620	            return newContent;
621	          });
622	          break;
623	        }
624	        case 'result': {
625	          const res = event.event as ClaudeResultEvent;
626	          setClaudeSessionId(res.session_id);
627	          if (typeof res.result === 'string' && res.result.trim()) {
628	            debugChat('claude result event', 'len', res.result.length);
629	            ensureTurnAssistantText(res.result);
630	          }
631	          break;
632	        }
633	        case 'unknown':
634	          break;
635	      }
636	    },
637	    [appendAssistantText, ensureTurnAssistantText, setClaudeSessionId, updateActiveAssistant]
638	  );
639	
640	  const handleCodexEvent = useCallback(
641	    (event: CodexStreamEvent) => {
642	      switch (event.type) {
643	        case 'threadStarted':
644	          setCodexSessionId(event.threadId);
645	          setModelName((prev) => prev ?? CODEX_MODEL);
646	          break;
647	        case 'assistantDelta':
648	          codexSawAssistantRef.current = true;
649	          debugChat('codex assistant delta', 'len', event.text.length);
650	          appendAssistantText(event.text);
651	          break;
652	        case 'commandBegin':
653	          updateActiveAssistant((newContent, targetIndex) => {
654	            const card: ToolUseCard = {
655	              toolUseId: event.commandId,
656	              toolName: 'Bash',
657	              input: { command: event.command },
658	              startedAt: Date.now(),
659	            };
660	            newContent.push({ type: 'toolUse', card });
661	            toolUseIndexRef.current.set(event.commandId, {
662	              messageIndex: targetIndex,
663	              toolName: 'Bash',
664	            });
665	            return newContent;
666	          });
667	          break;
668	        case 'commandEnd':
669	          updateActiveAssistant((newContent) => {
670	            const toolName = toolUseIndexRef.current.get(event.commandId)?.toolName ?? 'Bash';
671	            const resultCard: ToolResultCard = {
672	              toolUseId: event.commandId,
673	              toolName,
674	              content: event.output ?? null,
675	              completedAt: Date.now(),
676	            };
677	
678	            newContent.push({ type: 'toolResult', card: resultCard });
679	
680	            for (let i = 0; i < newContent.length; i++) {
681	              const item = newContent[i];
682	              if (item.type === 'toolUse' && item.card.toolUseId === event.commandId) {
683	                newContent[i] = {
684	                  type: 'toolUse',
685	                  card: { ...item.card, result: resultCard },
686	                };
687	                break;
688	              }
689	            }
690	            return newContent;
691	          });
692	          break;
693	        case 'turnCompleted':
694	          if (event.text && event.text.trim()) {
695	            debugChat('codex turn completed text', 'len', event.text.length);
696	            ensureTurnAssistantText(event.text);
697	          }
698	          if (event.model) setModelName(event.model);
699	          break;
700	        case 'error':
701	          setErrorMessage(event.message);
702	          break;
703	        case 'unknown':
704	          break;
705	      }
706	    },
707	    [appendAssistantText, ensureTurnAssistantText, updateActiveAssistant, setCodexSessionId]
708	  );
709	
710	  const reportCodexAuthIssue = useCallback(
711	    (raw: string) => {
712	      const issue = classifyCodexAuthIssue(raw);
713	      if (!issue) return;
714	      setCodexAuthIssue(issue);
715	      options.onCodexAuthIssue?.(issue);
716	    },
717	    [options.onCodexAuthIssue]
718	  );
719	
720	  const processServiceEvent = useCallback(
721	    (event: ServiceLogEvent) => {
722	      serviceEventsSeenRef.current += 1;
723	      debugChat('exec event', provider, event.type);
724	      switch (event.type) {
725	        case 'stdout': {
726	          if (!event.data) return;
727	          if (statusRef.current === 'connecting') setStatusTracked('streaming');
728	
729	          let dataStr = stripLogTimestamps(event.data);
730	          if (!dataStr.endsWith('\n')) dataStr += '\n';
731	
732	          if (provider === 'claude') {
733	            const events = claudeParserRef.current.parse(dataStr);
734	            if (events.length > 0) {
735	              debugChat('stdout parsed', provider, events.map((e) => e.type).join(','));
736	            }
737	            for (const parsed of events) {
738	              if (parsed.uuid && processedUUIDsRef.current.has(parsed.uuid)) continue;
739	              if (parsed.uuid) processedUUIDsRef.current.add(parsed.uuid);
740	              handleClaudeEvent(parsed);
741	            }
742	          } else {
743	            const events = codexParserRef.current.parse(dataStr);
744	            if (events.length > 0) {
745	              debugChat('stdout parsed', provider, events.map((e) => e.type).join(','));
746	            }
747	            for (const parsed of events) {
748	              handleCodexEvent(parsed);
749	            }
750	          }
751	          break;
752	        }
753	        case 'stderr': {
754	          if (statusRef.current === 'connecting') setStatusTracked('streaming');
755	          if (provider === 'codex' && event.data) {
756	            codexStderrRef.current += `\n${event.data}`;
757	          }
758	          break;
759	        }
760	        case 'exit': {
761	          const remaining =
762	            provider === 'claude'
763	              ? claudeParserRef.current.flush()
764	              : codexParserRef.current.flush();
765	
766	          if (provider === 'claude') {
767	            for (const parsed of remaining as ClaudeStreamEvent[]) {
768	              if (parsed.uuid && processedUUIDsRef.current.has(parsed.uuid)) continue;
769	              if (parsed.uuid) processedUUIDsRef.current.add(parsed.uuid);
770	              handleClaudeEvent(parsed);
771	            }
772	          } else {
773	            for (const parsed of remaining as CodexStreamEvent[]) {
774	              handleCodexEvent(parsed);
775	            }
776	          }
777	          break;
778	        }
779	        case 'error':
780	          if (event.data) setErrorMessage(event.data);
781	          break;
782	        case 'complete':
783	        case 'started':
784	        case 'stopping':
785	        case 'stopped':
786	          break;
787	      }
788	    },
789	    [handleClaudeEvent, handleCodexEvent, provider, setStatusTracked]
790	  );
791	  processServiceEventRef.current = processServiceEvent;
792	
793	  const sendMessage = useCallback(
794	    async (text?: string) => {
795	      if (statusRef.current !== 'idle') return;
796	
797	      const prompt = (text ?? inputText).trim();
798	      if (!prompt) return;
799	
800	      if (!text) setInputText('');
801	
802	      // Invalidate any in-flight history load to prevent clobbering this turn.
803	      loadRequestRef.current += 1;
804	      const historyBeforeSend = messagesRef.current;
805	
806	      const userMessage: ChatMessage = {
807	        id: makeId(),
808	        timestamp: Date.now(),
809	        role: 'user',
810	        content: [{ type: 'text', text: prompt }],
811	      };
812	
813	      const assistantMessage: ChatMessage = {
814	        id: makeId(),
815	        timestamp: Date.now(),
816	        role: 'assistant',
817	        content: [],
818	      };
819	
820	      activeUserMessageIdRef.current = userMessage.id;
821	      activeAssistantMessageIdRef.current = assistantMessage.id;
822	      assistantTextSeenRef.current = false;
823	      const pendingMessages = [...historyBeforeSend, userMessage, assistantMessage];
824	      updateMessages(() => pendingMessages);
825	      await saveChatMessages(chatId, pendingMessages);
826	      debugChat('sendMessage', provider, 'user', userMessage.id, 'assistant', assistantMessage.id);
827	
828	      const commandParts: string[] = [];
829	
830	      // Credentials (git identity, GitHub HTTPS auth, Claude OAuth) are written
831	      // to the sprite once — at creation, or lazily here on first use this
832	      // session — so they aren't re-sent on every chat command.
833	      await ensureProvisionedOnce(spriteName);
834	
835	      commandParts.push(`mkdir -p ${shellQuote(workingDirectory)}`);
836	      commandParts.push(`cd ${shellQuote(workingDirectory)}`);
837	      // Load the persisted Claude OAuth token (env-var path); harmless no-op when
838	      // a captured login credentials file is used instead.
839	      commandParts.push('. ~/.sprite_env 2>/dev/null || true');
840	
841	      if (provider === 'claude') {
842	        const claudePrompt = claudeSessionIdRef.current
843	          ? prompt
844	          : buildFallbackPrompt(historyBeforeSend, prompt);
845	
846	        commandParts.push('export NO_DNA=1');
847	
848	        let claudeCmd =
849	          'claude -p --verbose --output-format stream-json --dangerously-skip-permissions';
850	
851	        const [modelId, maxTurns, customInstructions] = await Promise.all([
852	          getSetting('claudeModel'),
853	          getSetting('maxTurns'),
854	          getSetting('customInstructions'),
855	        ]);
856	
857	        claudeCmd += ` --model ${shellQuote(modelId ?? 'sonnet')}`;
858	
859	        if (maxTurns && maxTurns !== '0') {
860	          claudeCmd += ` --max-turns ${shellQuote(maxTurns)}`;
861	        }
862	
863	        if (customInstructions && customInstructions.trim()) {
864	          claudeCmd += ` --append-system-prompt ${shellQuote(customInstructions)}`;
865	        }
866	
867	        if (claudeSessionIdRef.current) {
868	          claudeCmd += ` --resume ${shellQuote(claudeSessionIdRef.current)}`;
869	        }
870	        claudeCmd += ` ${shellQuote(claudePrompt)}`;
871	
872	        commandParts.push(claudeCmd);
873	      } else {
874	        setModelName(CODEX_MODEL);
875	        const codexPrompt = codexSessionIdRef.current
876	          ? prompt
877	          : buildFallbackPrompt(historyBeforeSend, prompt);
878	
879	        const codexCmd = codexSessionIdRef.current
880	          ? `codex exec resume ${shellQuote(codexSessionIdRef.current)} --json --model ${CODEX_MODEL} --skip-git-repo-check --dangerously-bypass-approvals-and-sandbox ${shellQuote(codexPrompt)}`
881	          : `codex exec --json --model ${CODEX_MODEL} --skip-git-repo-check --dangerously-bypass-approvals-and-sandbox ${shellQuote(codexPrompt)}`;
882	
883	        commandParts.push(codexCmd);
884	      }
885	
886	      const taskName = safeTaskName(`wisp-chat-${provider}-${userMessage.id}`);
887	      const fullCommand = withSpriteTaskHeartbeat(commandParts.join(' && '), taskName);
888	
889	      processedUUIDsRef.current = new Set();
890	      claudeParserRef.current.reset();
891	      codexParserRef.current.reset();
892	      codexStderrRef.current = '';
893	      codexSawAssistantRef.current = false;
894	      setStatusTracked('connecting');
895	      setErrorMessage(undefined);
896	      setCodexAuthIssue(undefined);
897	      serviceEventsSeenRef.current = 0;
898	
899	      const abortController = new AbortController();
900	      abortRef.current = abortController;
901	      execSessionIdRef.current = undefined;
902	
903	      try {
904	        await api.streamExec(
905	          spriteName,
906	          ['bash', '-c', fullCommand],
907	          processServiceEvent,
908	          abortController.signal,
909	          {
910	            path: '/bin/bash',
911	            maxRunAfterDisconnect: '0',
912	            onSessionId: (sessionId) => {
913	              execSessionIdRef.current = sessionId;
914	              setActiveRun({
915	                execSessionId: sessionId,
916	                taskName,
917	                provider,
918	                userMessageId: userMessage.id,
919	                assistantMessageId: assistantMessage.id,
920	                workingDirectory,
921	                startedAt: Date.now(),
922	              });
923	            },
924	          }
925	        );
926	      } catch (err: any) {
927	        if (err.name !== 'AbortError') {
928	          const message = err.message ?? 'Stream error';
929	          debugChat('stream error', provider, message);
930	          setErrorMessage(message);
931	          if (provider === 'codex') {
932	            reportCodexAuthIssue(`${message}\n${codexStderrRef.current}`);
933	          }
934	        }
935	      } finally {
936	        const remaining =
937	          provider === 'claude' ? claudeParserRef.current.flush() : codexParserRef.current.flush();
938	
939	        if (provider === 'claude') {
940	          for (const parsed of remaining as ClaudeStreamEvent[]) {
941	            if (parsed.uuid && processedUUIDsRef.current.has(parsed.uuid)) continue;
942	            if (parsed.uuid) processedUUIDsRef.current.add(parsed.uuid);
943	            handleClaudeEvent(parsed);
944	          }
945	        } else {
946	          for (const parsed of remaining as CodexStreamEvent[]) {
947	            handleCodexEvent(parsed);
948	          }
949	        }
950	
951	        if (provider === 'codex' && !codexSawAssistantRef.current) {
952	          reportCodexAuthIssue(codexStderrRef.current);
953	        }
954	
955	        if (abortRef.current === abortController) {
956	          abortRef.current = null;
957	        }
958	        setActiveRun(undefined);
959	        execSessionIdRef.current = undefined;
960	        activeUserMessageIdRef.current = undefined;
961	        activeAssistantMessageIdRef.current = undefined;
962	        assistantTextSeenRef.current = false;
963	        setStatusTracked('idle');
964	        persistMessages();
965	      }
966	    },
967	    [
968	      inputText,
969	      chatId,
970	      persistMessages,
971	      processServiceEvent,
972	      provider,
973	      reportCodexAuthIssue,
974	      setActiveRun,
975	      setStatusTracked,
976	      spriteName,
977	      handleClaudeEvent,
978	      handleCodexEvent,
979	      updateMessages,
980	      workingDirectory,
981	    ]
982	  );
983	
984	  const interrupt = useCallback(() => {
985	    const sessionId = execSessionIdRef.current;
986	    if (sessionId) {
