const KEPT=new Set(['event_msg:user_message','event_msg:agent_message','response_item:function_call','response_item:function_call_output','response_item:custom_tool_call','response_item:custom_tool_call_output','response_item:web_search_call']);
const kept=[];
for(const line of fs.readFileSync(file,'utf8').split('\n')){if(!line.trim())continue;let o;try{o=JSON.parse(line)}catch{continue}const p=o&&o.payload;const key=o&&o.type+':'+(p&&p.type);if(key&&KEPT.has(key))kept.push(line);}
console.log('kept lines:',kept.length, 'of raw; size KB:', Math.round(kept.join('\n').length/1024));

// mapping port
function commandFromArgs(a){if(typeof a!=='string')return'command';let j;try{j=JSON.parse(a)}catch{return a}if(j&&typeof j.cmd==='string')return j.cmd;if(j&&Array.isArray(j.command))return j.command.join(' ');return'command';}
function patchFirstFile(p){if(typeof p!=='string')return;const m=p.match(/\*\*\* (?:Add|Update|Delete) File: (.+)/);return m?m[1].trim():undefined;}
const messages=[];const loc=new Map();let cur=null;
const ensure=()=>{if(cur!==null)return cur;messages.push({role:'assistant',content:[]});cur=messages.length-1;return cur;};
const pushTool=(i,c)=>{messages[i].content.push({type:'toolUse',card:c});loc.set(c.toolUseId,i);};
const appendText=(i,t)=>{const n=messages[i].content;const l=n[n.length-1];if(l&&l.type==='text')l.text+='\n'+t;else n.push({type:'text',text:t});};
const attach=(id,out)=>{const i=loc.get(id);if(i===undefined)return;for(const it of messages[i].content){if(it.type==='toolUse'&&it.card.toolUseId===id){it.card.result={content:out};}}messages[i].content.push({type:'toolResult',card:{toolUseId:id}});};
for(const line of kept){let o;try{o=JSON.parse(line)}catch{continue}const p=o.payload;const key=o.type+':'+p.type;
 if(key==='event_msg:user_message'){if(!String(p.message||'').trim())continue;messages.push({role:'user',content:[{type:'text',text:p.message}]});cur=null;}
 else if(key==='event_msg:agent_message'){if(!String(p.message||'').trim())continue;appendText(ensure(),p.message);}
 else if(key==='response_item:function_call'){const id=p.call_id||p.id;pushTool(ensure(),{toolUseId:id,toolName:'Bash',input:{command:commandFromArgs(p.arguments)}});}
 else if(key==='response_item:function_call_output'){if(p.call_id)attach(p.call_id,p.output);}
 else if(key==='response_item:custom_tool_call'){const id=p.call_id||p.id;const isP=p.name==='apply_patch';pushTool(ensure(),{toolUseId:id,toolName:isP?'Edit':p.name,input:isP?{file_path:patchFirstFile(p.input)}:{}});}
 else if(key==='response_item:custom_tool_call_output'){if(p.call_id)attach(p.call_id,p.output);}
 else if(key==='response_item:web_search_call'){const id=p.id||p.call_id;pushTool(ensure(),{toolUseId:id,toolName:'WebSearch',input:{query:p.action&&p.action.query}});}
}
console.log('messages:',messages.length,'| users:',messages.filter(m=>m.role==='user').length,'| assistants:',messages.filter(m=>m.role==='assistant').length);
console.log('\n--- summary of first 8 messages ---');
for(const m of messages.slice(0,8)){
  const parts=m.content.map(c=>c.type==='text'?`text(${c.text.slice(0,40).replace(/\n/g,' ')})`:c.type==='toolUse'?`tool:${c.card.toolName}[${(c.card.input.command||c.card.input.file_path||c.card.input.query||'').slice(0,30)}]${c.card.result?'✓':''}`:c.type);
  console.log(`[${m.role}]`, parts.join('  '));
}
// check unresolved tools
let tools=0,resolved=0;for(const m of messages)for(const c of m.content)if(c.type==='toolUse'){tools++;if(c.card.result)resolved++;}
console.log('\ntools:',tools,'resolved:',resolved);
